CREATE TABLE IF NOT EXISTS users (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL,
  password_hash VARCHAR(255) NOT NULL, created_at VARCHAR(40) NOT NULL,
  UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sessions (token VARCHAR(255) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, created_at VARCHAR(40) NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS friends (user_id BIGINT UNSIGNED NOT NULL, friend_id BIGINT UNSIGNED NOT NULL, created_at VARCHAR(40) NOT NULL, PRIMARY KEY(user_id,friend_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(friend_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settlements (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, public_token VARCHAR(255) NOT NULL, bank VARCHAR(100) NOT NULL, account VARCHAR(255) NOT NULL, total_amount BIGINT NOT NULL, created_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_settlements_public_token(public_token), FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settlement_participants (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, settlement_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NULL, name VARCHAR(100) NOT NULL, amount BIGINT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', paid_at VARCHAR(40) NULL, transaction_id VARCHAR(255) NULL, UNIQUE KEY uq_transaction(transaction_id), KEY idx_participants_settlement(settlement_id), FOREIGN KEY(settlement_id) REFERENCES settlements(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS receipts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, settlement_id BIGINT UNSIGNED NOT NULL, receipt_index INT NOT NULL, total_amount BIGINT NOT NULL, items_json JSON NOT NULL, KEY idx_receipts_settlement(settlement_id), FOREIGN KEY(settlement_id) REFERENCES settlements(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(50) NOT NULL, title VARCHAR(255) NOT NULL, message TEXT NOT NULL, settlement_id BIGINT UNSIGNED NULL, `read` TINYINT(1) NOT NULL DEFAULT 0, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settlement_requests (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, request_id VARCHAR(128) NOT NULL, settlement_id BIGINT UNSIGNED NOT NULL, UNIQUE KEY uq_owner_request(owner_id,request_id), FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(settlement_id) REFERENCES settlements(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
